# Input 2s (r, c):
points = [(3, 8), (6, 4), (6, 12), (9, 10), (11, 7)]

# Output 3s:
output_3s = {(4,8), (5,8), (6,5), (6,6), (6,7), (6,8), (6,9), (6,10), (6,11), 
             (7,7), (7,10), (8,7), (8,10), (9,7), (10,7)}

# Check which 2s contribute to each 3:
def on_ray_from(p_source, p_target):
    """Check if p_target is on a ray from p_source (N, E, S, W directions only)"""
    rsrc, csrc = p_source
    rtgt, ctgt = p_target

    # Check all 4 directions
    # N: same col, target above source
    if ctgt == csrc and rtgt < rsrc:
        for dr in range(1, rsrc - rtgt):
            mid_r, mid_c = rsrc - dr, csrc
            if (mid_r, mid_c) in points:
                return False
        return True

    # S: same col, target below source
    if ctgt == csrc and rtgt > rsrc:
        for dr in range(1, rtgt - rsrc):
            mid_r, mid_c = rsrc + dr, csrc
            if (mid_r, mid_c) in points:
                return False
        return True

    # E: same row, target right of source
    if rtgt == rsrc and ctgt > csrc:
        for dc in range(1, ctgt - csrc):
            mid_r, mid_c = rsrc, csrc + dc
            if (mid_r, mid_c) in points:
                return False
        return True

    # W: same row, target left of source
    if rtgt == rsrc and ctgt < csrc:
        for dc in range(1, csrc - ctgt):
            mid_r, mid_c = rsrc, csrc - dc
            if (mid_r, mid_c) in points:
                return False
        return True

    return False

# For each output 3, find which input 2s it should be connected to
for (r, c) in sorted(output_3s):
    contributors = [p for p in points if on_ray_from(p, (r, c))]
    if contributors:
        print(f"({r},{c}): from {contributors}")
    else:
        print(f"({r},{c}): NO CONTRIBUTOR!")

