    output[r][c] = 2

# Horizontal connections on hub rows
for hub_r in hub_rows:
    hub_2s = [p for p in test_2s if p[0] == hub_r]
    for i in range(len(hub_2s)):
        for j in range(i+1, len(hub_2s)):
            start, end = min(hub_2s[i][1], hub_2s[j][1]), max(hub_2s[i][1], hub_2s[j][1])
            for c in range(start + 1, end):
                if output[hub_r][c] == 0:
                    output[hub_r][c] = 3

print("\nHorizontal connections:")
for r in range(test_rows):
    for c in range(test_cols):
        if output[r][c] == 3:
            print(f"({r},{c})", end=",")

# Vertical connections: extra rows connect to nearest hub row
for extra_r in extra_rows:
    extra_cols = [c for p in test_2s if p[0] == extra_r][0]
    for hub_r in hub_rows:
        # Determine direction
