            while r < hub_r:
                r += 1
                output[r][c] = 3
                # Stop if we would pass the hub
                if r == hub_r:
                    break
        else:  # extra_r > hub_r
            direction = "UP"
            # Start from extra row going toward hub
            r, c = extra_r, extra_cols
            while r > hub_r:
                r -= 1
                output[r][c] = 3
                if r == hub_r:
                    break

print("\nVertical connections:")
for r in range(test_rows):
    for c in range(test_cols):
        if output[r][c] == 3:
            print(f"({r},{c})", end=",")

# Print final output
